from freeze import *
import collections,sys
def main():
 events=[json.loads(x) for x in (STUDY/'ATTEMPTS.jsonl').read_text().splitlines()];starts=[x for x in events if x['event']=='START'];ends={x['id']:x for x in events if x['event']=='END'};active=[x['id'] for x in starts if x['id'] not in ends]
 phase=sys.argv[1] if len(sys.argv)>1 else 'INITIAL_GROUPED_DATA'
 data=[json.loads(p.read_text()) for p in (STUDY/'output').glob('*_DATA.json')];counts=collections.Counter((r['split'],r['group']) for r in data);valid=sum(r.get('metric',{}).get('valid',False) for r in data);qualified=sum(bool(r.get('metric',{}).get('valid') and r.get('metric',{}).get('matched_eligible') and r.get('metric',{}).get('status')=='COMPLETE') for r in data)
 state=dict(phase=phase,start_unix=1791222386,updated_unix=time.time(),elapsed_s=time.time()-1791222386,attempts=len(starts),complete_attempt_events=len(ends),active=active,data_branches=len(data),valid_data_branches=valid,group_counts={str(k):v for k,v in counts.items()},next_action='Finish initial grouped train/development labels; fit only when physics is idle; run 16-task four-group 2x2 before further data expansion',runner_pid=(STUDY/'runner.lock').read_text(),remaining_physics_budget=300-len(starts),original_deadline_unix=1791222386+16*3600,learning_development_iterations=0,information_condition='KNOWN_MODEL')
 save(STUDY/'STATE.json',state)
 state['qualified_data_branches']=qualified
 next_actions={'WAIT_INITIAL_DATA':'Finish grouped train/dev labels and timing/streaming-fork regressions, fit v1, then small complete 2x2','WAIT_V1_CORE':'Finish 16 paired v1 closed-loop tests, analyze and run development-only full-consequence diagnosis','WAIT_DATA_EXTENSION':'Complete one bounded legal-state coverage extension, then second/final development fit','WAIT_V2_FINAL':'Finish untouched v2 final paired tests before held-out same-state audit','WAIT_HELDOUT_AUDIT':'Finish fixed-pool physical consequences, compare same-pool V ranking and K3 multi-step direction','WAIT_RESERVED_VALIDATION':'Finish fresh paired tests with independent training initialization, then check pilot gate'}
 next_actions.update(WAIT_EXTRA_VALIDATION='Finish preregistered untouched tests using frozen independent weights; no tuning or retroactive pilot promotion',WAIT_TAIL_VALIDATION='Finish only the untouched groups allowed by actual spare slots',CORE_COMPARISON_COMPLETE='Campaign complete; all owned workers joined; no further dispatch')
 state['next_action']=next_actions.get(phase,phase);state['learning_development_iterations']=2 if phase in ('WAIT_V2_FINAL','WAIT_HELDOUT_AUDIT','WAIT_RESERVED_VALIDATION','RESERVED_VALIDATION_COMPLETE','WAIT_EXTRA_VALIDATION','WAIT_TAIL_VALIDATION','CORE_COMPARISON_COMPLETE') else 1 if phase in ('WAIT_V1_CORE','WAIT_DATA_EXTENSION') else 0;save(STUDY/'STATE.json',state)
 (STUDY/'PROGRESS.md').write_text(f'Phase: {phase}\nElapsed: {state["elapsed_s"]/3600:.2f}/16 h\nPhysics attempts (failures/parents/branches included): {len(starts)}/300\nActive: {active}\nData branches: {len(data)}; physical/scientific VALID: {valid}; complete VALID+MATCHED: {qualified}\nNext: {state["next_action"]}\n')
 print(json.dumps({k:state[k] for k in ('phase','elapsed_s','attempts','active','data_branches','valid_data_branches')}))
if __name__=='__main__':main()
